package catalog

import (
	"bytes"
	"encoding/json"
	"fmt"
	"regexp"
)

// HistoryV2 is a variant's history.json, generated by the catalog's Pages build
// from git: every revision of the variant file, newest first.
type HistoryV2 struct {
	Model     string       `json:"model"`
	ID        string       `json:"id"`
	Path      string       `json:"path"`
	Revisions []RevisionV2 `json:"revisions"`
	// Deleted is the commit that removed the file, once it is gone.
	Deleted *DeletionV2 `json:"deleted,omitempty"`
}

// RevisionV2 is one version of a variant file. Commit and ReleaseDate are
// absent from a revision that was never committed, which only a local build
// publishes.
type RevisionV2 struct {
	Version     string `json:"version"`
	ReleaseDate string `json:"releaseDate,omitempty"`
	Commit      string `json:"commit,omitempty"`
	Digest      string `json:"digest"`
	Subject     string `json:"subject,omitempty"`
}

type DeletionV2 struct {
	Commit  string `json:"commit,omitempty"`
	Subject string `json:"subject,omitempty"`
}

var commitRE = regexp.MustCompile(`^[0-9a-f]{40}$`)

// parseHistoryV2 decodes a history.json and checks it against the index entry
// it was reached from: the same variant file, and its newest revision the one
// the index pins. Unknown keys are ignored, as in the index it is published
// beside.
func parseHistoryV2(b []byte, model string, pin VariantPinV2) (HistoryV2, error) {
	var h HistoryV2
	if err := json.NewDecoder(bytes.NewReader(b)).Decode(&h); err != nil {
		return HistoryV2{}, err
	}
	if h.Model != model || h.ID != pin.ID || h.Path != pin.Path {
		return HistoryV2{}, fmt.Errorf("history is of %s/%s (%s), not %s/%s (%s)", h.Model, h.ID, h.Path, model, pin.ID, pin.Path)
	}
	if len(h.Revisions) == 0 {
		return HistoryV2{}, fmt.Errorf("history lists no revisions")
	}
	if top := h.Revisions[0]; top.Version != pin.Version || top.Digest != pin.Digest {
		return HistoryV2{}, fmt.Errorf("history's newest revision is %s (%s), the index pins %s (%s) -- history is stale", top.Version, top.Digest, pin.Version, pin.Digest)
	}
	seen := map[string]bool{}
	for i, r := range h.Revisions {
		switch {
		case r.Version == "" || r.Digest == "":
			return HistoryV2{}, fmt.Errorf("revisions[%d] needs both version and digest", i)
		case seen[r.Version]:
			return HistoryV2{}, fmt.Errorf("version %s is listed twice", r.Version)
		case r.Commit != "" && !commitRE.MatchString(r.Commit):
			return HistoryV2{}, fmt.Errorf("version %s: commit %q is not a 40-character sha", r.Version, r.Commit)
		}
		seen[r.Version] = true
	}
	return h, nil
}

// revision looks a version up.
func (h HistoryV2) revision(version string) (RevisionV2, bool) {
	for _, r := range h.Revisions {
		if r.Version == version {
			return r, true
		}
	}
	return RevisionV2{}, false
}

func (h HistoryV2) versions() string {
	out := ""
	for i, r := range h.Revisions {
		if i > 0 {
			out += ", "
		}
		out += r.Version
	}
	return out
}
